//this will setup the needed hardware resourrces which i got from my assembly code and used machine translation
void config(){
		//accoridng to google this is a setting I need to enable for this called DBGMCU_CR that allows the debugger to handle this
	    DBGMCU->CR |= (1 << 0);
	    //GPIO clocks
	    RCC->AHB1ENR |= (1 << 0) | (1 << 1);
	    //port A set pins 5,6,7 as inputs
	    GPIOA->MODER &= ~((3 << 10) |
	                      (3 << 12) |
	                      (3 << 14));
	    //clear the pupdr
	    GPIOA->PUPDR &= ~((3 << 10) |
	                      (3 << 12) |
	                      (3 << 14));
	    //use the pull down this might affect you if your button is set weird so make sure the button uses active high
	    GPIOA->PUPDR |= (2 << 10) |
	                    (2 << 12) |
	                    (2 << 14);
	    //set PB5 to alternate mode
	    GPIOB->MODER &= ~(3 << 10);
	    GPIOB->MODER |=  (2 << 10);
	    //select AF2
	    GPIOB->AFR[0] &= ~(0xF << 20);
	    GPIOB->AFR[0] |=  (2 << 20);
	    //enable TIM3 clock
	    RCC->APB1ENR |= RCC_APB1ENR_TIM3EN;
	    //stop timer
	    TIM3->CR1 = 0;
	    //1 MHz
	    TIM3->PSC = 15;
	    //1 kHz
	    TIM3->ARR = 999;
	    //50% duty cycle
	    TIM3->CCR2 = 500;
	    //configure channel 2 for PWM mode 1
	    TIM3->CCMR1 &= ~(3 << 8);
	    TIM3->CCMR1 &= ~(7 << 12);
	    TIM3->CCMR1 |=  (6 << 12);
	    TIM3->CCMR1 |= TIM_CCMR1_OC2PE;
	    //enable channel 2 output
	    TIM3->CCER |= TIM_CCER_CC2E;
	    //enable preload
	    TIM3->CR1 |= TIM_CR1_ARPE;
	    //event registers
	    TIM3->EGR = TIM_EGR_UG;
	    //start timer
	    TIM3->CR1 |= TIM_CR1_CEN;
	    //TIM5 clock
	    RCC->APB1ENR |= (1 << 3);
	    //TIM5 configuration
	    TIM5->PSC = 15999;
	    TIM5->ARR = 0xFFFFFFFF;
	    TIM5->EGR = TIM_EGR_UG;
	    TIM5->SR = 0;
	    TIM5->CNT = 0;
	    // Configure one-shot duration timer
	    TIM5->CR1 &= ~TIM_CR1_CEN;
		//enable interupt
		TIM5->DIER |= TIM_DIER_UIE;
		//one pulse mode since we only need a single interupt
		TIM5->CR1 |= TIM_CR1_OPM;
		//start this timer
		TIM5->CR1 |= TIM_CR1_CEN;
	    //SYSCFG clock
	    RCC->APB2ENR |= RCC_APB2ENR_SYSCFGEN;
	    //map EXTI5-7 to GPIOA
	    SYSCFG->EXTICR[1] &= ~((0xF << 4) |
	                           (0xF << 8) |
	                           (0xF << 12));
	    uint32_t mask = (1 << 5) |
	                    (1 << 6) |
	                    (1 << 7);
	    //falling trigger
	    EXTI->FTSR |= mask;
	    EXTI->RTSR &= ~mask;
	    //enable interrupts
	    EXTI->IMR |= mask;
	    //clear pending flags
	    EXTI->PR = mask;
	    //nvic for buttons
	    NVIC_SetPriority(EXTI9_5_IRQn, 2);
	    NVIC_EnableIRQ(EXTI9_5_IRQn);
	    //nvic for tim5
	    NVIC_SetPriority(TIM5_IRQn, 3);
	    NVIC_EnableIRQ(TIM5_IRQn);
}
void debounceHandler(volatile uint32_t *time, int8_t pin){
		uint32_t mask = (1 << pin);
	    //check if button is pressed
	    if (!(GPIOA->IDR & mask)) {
	        *time = TIM5->CNT;
	        return;
	    }
	    //check delta time
	    uint32_t elapsed = TIM5->CNT - *time;
	    if (elapsed < 25) {
	        return;
	    }
	    //final check
	    if (!(GPIOA->IDR & mask)) {
	        *time = TIM5->CNT;
	        return;
	    }
	    //button successfully debounced
	    *time = 0;
	    debounceState &= ~(1 << pin);
	    //enable EXTI for this pin
	    EXTI->PR = mask;
	    EXTI->IMR |= mask;
}

int main(void) {
		//enable floating point operations
		SCB->CPACR |= (0xF << 20);
		__DSB();
		__ISB();
		noteSpeed = (MS_IN_MIN + (song1.bpm * song1.beat_resolution /2)) / (song1.bpm * song1.beat_resolution);
		//how to connect songs
		song1.next = &song2;
		song2.prev = &song1;
		song2.next = &song3;
		song3.prev = &song2;
		//last make sure to change this if you add a song for example song1.prev should equal the song you added
		//then the previous last song should point to next last song
		//overall you only need to change 4 things song1.prev, previousLastSong.next, and the new song prev and next
		song1.prev = &song3;
		song3.next = &song1;
		current = &song1;
	config();
	TIM3->CCR2 = 0;
	int8_t tracker = 0;
	uint32_t duration;
	while(1){
		switch(state){ //state machine
			case 0:		//sleeper
				 __disable_irq();
				 if (state == 0) {
					 __DSB();
					 __WFI();
				  }
				  __enable_irq();
				  break;
			case 1:	//button debounce code
				while(debounceState != 0) {
					switch(tracker) {
						case 0: //each case is a button
							if(timestamp1 != 0){ //if timestamp not 0 then we do a processing
								debounceHandler(&timestamp1, 5);
							}
							tracker += 1;
							break;
						case 1:
							if(timestamp2 != 0){
								debounceHandler(&timestamp2, 6);
							}
							tracker += 1;
							break;
						case 2:
							if(timestamp3 != 0){
								debounceHandler(&timestamp3, 7);
							}
							tracker = 0;
							break;
					}
				}
				//must keep this safe otherwise we get stale data
				__disable_irq();
				TIM5->CR1 &= ~TIM_CR1_CEN;
				TIM5->DIER &= ~TIM_DIER_UIE;
				TIM5->CR1 |= TIM_CR1_OPM;
				TIM5->CNT = 0;
				TIM5->SR &= ~TIM_SR_UIF;
				isSet = 0;
				TIM5->DIER |= TIM_DIER_UIE;
				__enable_irq();
				if(isPaused == 1){//paused the opcode 0 for sleep otherwise run
					state = 0;
				}else if(isSet == 1){
					state = 1;
				}else{
					state = 2;
				}
				break;
			case 2: //this is the music player
				if(counter == current->length){ //if at length were done with song
					//set to sleep
					state = 0;
					//setpaused true
					isPaused = 1;
					//back to zero
					counter = 0;
					break;
				}
				// duration is time per note * the amount of beats
				duration = noteSpeed * current->beat[counter];
				if (current->music[counter] == 0){
					//if 0 we are resting so turn this shit off
					TIM3->CCR2 = 0;
				}else {
					// counter frequecny divided by our notes frequncy (1mhz / frequency of note) -1
					TIM3->ARR = (1000000 / notes[current->music[counter]]) - 1;
					// powermode determines how long our pwm stays high here is 50% powermode for every note
					TIM3->CCR2 = (TIM3->ARR + 1) / 2;
					//event sent immediately in TIM3
					TIM3->EGR = TIM_EGR_UG;
				}
				//array index update first
				counter += 1;
				//stop timer since we will change settings
				TIM5->CR1 &= ~TIM_CR1_CEN;
				 //reset counter
				TIM5->CNT = 0;
				//set the time for when interupt will treigger
				TIM5->ARR = duration - 1;
				//clear any old updates
				TIM5->SR &= ~TIM_SR_UIF;
				//start the timer
				TIM5->CR1 |= TIM_CR1_CEN;
				__disable_irq();
				if (debounceState == 0 && isDone == 0) {
				    __DSB();
				    __WFI();
				}
				__enable_irq();
				//turn buzzer off
				isDone = 0;
				break;
		}
	}
}

//i pretty much copied the design from the previous LAB3
void EXTI9_5_IRQHandler(void) {
    uint32_t pending = EXTI->PR;
    uint32_t pin;
    //turn off buzzer
    	TIM3->CCR2 = 0;
    	if(isSet == 0){
    		//stop timer
    		TIM5->CR1 &= ~TIM_CR1_CEN;
    		//disable update interrupt
    		TIM5->DIER &= ~TIM_DIER_UIE;
    		//disable one pulse mode
    		TIM5->CR1 &= ~TIM_CR1_OPM;
    		//set cnt to 0
    		TIM5->CNT = 1;
    		//max out the timer
    		TIM5->ARR = 0xFFFFFFFF;
    		//clear tim5 interupts
    		TIM5->SR &= ~TIM_SR_UIF;
    		//start timer
    		TIM5->CR1 |= TIM_CR1_CEN;
    		isSet = 1;
    	}
    volatile uint32_t *timeVariable;
    //left
    if (pending & (1 << 5)){
    	//set to previous song
    	current = current->prev;
    	//notespeed is time spent per note
    	noteSpeed = (MS_IN_MIN + (current->bpm * current->beat_resolution / 2)) / (current->bpm * current->beat_resolution);
    	//array index
    	counter = 0;
    	// is the loop paused answer is no
    	isPaused = 0;
    	//state machine op code for debounce
    	state = 1;
        pin = 5;
        debounceState |= (1 << pin);
        timeVariable = &timestamp1;
    }
    //stop or play
    else if (pending & (1 << 6)) {
    	//is the loop paused answer is yes
    	isPaused ^= 1;
    	//state machine op code for debounce
    	state = 1;
        pin = 6;
        //flip state on
        debounceState |= (1 << pin);
        timeVariable = &timestamp2;
    }
    //right
    else if (pending & (1 << 7)) {
    	//set to previous song
    	current = current->next;
    	//notespeed is time spent per note
    	noteSpeed = (MS_IN_MIN + (current->bpm * current->beat_resolution / 2)) / (current->bpm *current->beat_resolution);
    	//array index
    	counter = 0;
    	//state machine op code for debounce
    	state = 1;
    	//is the loop paused answer is no
    	isPaused = 0;
        pin = 7;
        //flip state on
        debounceState |= (1 << pin);
        timeVariable = &timestamp3;
    }
    else {
        return;
    }
    //disable EXTI for this pin
    EXTI->IMR &= ~(1 << pin);
    //save current timer count
    *timeVariable = TIM5->CNT;
    //clear pending interrupt flag
    EXTI->PR = (1 << pin);
}
void TIM5_IRQHandler(void) {
	//this will check for TIM5 timer and update
    if (TIM5->SR & TIM_SR_UIF) {
    	//turn off
    	TIM3->CCR2 = 0;
    	//this is so we know we finished bnefore the if statement, rare but possible
    	isDone = 1;
    	//clear the pending interupt flag
        TIM5->SR &= ~TIM_SR_UIF;
    }
}
